// src/controllers/auth.controller.ts
var handleRegister = async (req, res, next) => {
  try {
    const { name, email, password } = req.body;
    if (!name || !email || !password) {
      throw createHttpError3.BadRequest("Name, email and password are required");
    }
    const { user, access_token, refresh_token } = await registerUser(
      name,
      password,
      email
    );
    return res.status(201).json({
      message: "User registered successfully",
      user,
      access_token,
      refresh_token
    });
  } catch (error) {
    next(error);
  }
};
var handleLogin = async (req, res, next) => {
  try {
    const { email, password } = req.body;
    if (!email || !password) {
      throw createHttpError3.BadRequest("Email and password are required");
    }
    const { user, access_token, refresh_token } = await loginUser(
      email,
      password
    );
    return res.status(200).json({
      message: "Login successful",
      user,
      access_token,
      refresh_token
    });
  } catch (error) {
    next(error);
  }
};
var handleGetUsers = async (req, res, next) => {
  try {
    const { id, name, email } = req.query;
    const users = await getUsers(id, name, email);
    return res.status(200).json({
      message: "Users retrieved successfully",
      users
    });
  } catch (error) {
    next(error);
  }
};
var handleRefreshToken = async (req, res, next) => {
  try {
    const token = req.headers.authorization?.split(" ")[1];
    if (!token) {
      throw createHttpError3.BadRequest("Invalid token");
    }
    const { access_token, user } = await refreshToken(token);
    return res.status(200).json({
      message: "Token refreshed successfully",
      access_token,
      user
    });
  } catch (error) {
    next(error);
  }
};
var handleRequestPasswordReset = async (req, res, next) => {
  try {
    const { email } = req.body;
    if (!email) {
      return res.status(400).json({ message: "Email is required" });
    }
    const result = await requestResetPassword(email);
    return res.status(200).json(result);
  } catch (error) {
    next(error);
  }
};
var handleVerifyOTP = async (req, res, next) => {
  try {
    const { email, otp, purpose } = req.body;
    if (!email || !otp || !purpose) {
      return res.status(400).json({
        message: "Email, OTP, and purpose are required"
      });
    }
    if (!isValidOtpPurpose(purpose)) {
      return res.status(400).json({ message: "Invalid OTP purpose" });
    }
    const resetToken = await checkOTP(email, otp, purpose);
    return res.status(200).json({
      message: "OTP verified successfully",
      reset_token: resetToken
    });
  } catch (error) {
    next(error);
  }
};
var handleResetPassword = async (req, res, next) => {
  try {
    const { token, newPassword } = req.body;
    if (!token || !newPassword) {
      return res.status(400).json({
        message: "Token and new password are required"
      });
    }
    const result = await resetPassword(token, newPassword);
    return res.status(200).json(result);
  } catch (error) {
    next(error);
  }
};

// src/middleware/middleware.ts
import createHttpError4 from "http-errors";
var authMiddleware = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      throw createHttpError4.Unauthorized("Invalid authorization format");
    }
    const token = authHeader.split(" ")[1];
    if (!token) {
      throw createHttpError4.Unauthorized("Invalid authorization format");
    }
    const decoded = verifyToken(token, "access");
    req.user = decoded;
    next();
  } catch {
    logger_default.warn(`Unauthorized access attempt - ${req.method} ${req.url}`);
    next(createHttpError4.Unauthorized("Invalid token"));
  }
};

// src/middleware/validate.middleware.ts
import createHttpError5 from "http-errors";
var validate = (schema) => {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      const message = result.error.issues[0]?.message ?? "Invalid request body";
      return next(createHttpError5.BadRequest(message));
    }
    req.body = result.data;
    next();
  };
};

