var getTrustProxy = (raw2 = process.env.TRUST_PROXY) => {
  const value = raw2?.trim();
  if (!value || value.toLowerCase() === "false") return false;
  if (value.toLowerCase() === "true") {
    throw new Error(
      "TRUST_PROXY=true trusts arbitrary clients. Use a hop count or explicit proxy CIDRs."
    );
  }
  if (/^\d+$/.test(value)) return Number.parseInt(value, 10);
  return value.split(",").map((entry) => entry.trim()).filter(Boolean);
};

// src/app.ts
var app = express();
var allowedOrigins = getAllowedOrigins();
app.disable("x-powered-by");
app.set("trust proxy", getTrustProxy());
morgan.token("client-ip", (req) => {
  return req.ip || req.socket.remoteAddress || "unknown";
});
app.use(
  morgan(":client-ip :method :url :status :response-time ms", {
    stream: {
      write: (message) => logger_default.http(message.trim())
    }
  })
);
app.use(helmet());
app.use(express.json({ limit: "100kb" }));
app.use(urlencoded({ extended: false, limit: "100kb", parameterLimit: 100 }));
app.use(
  cors({
    origin(origin, callback) {
      if (isOriginAllowed(origin, allowedOrigins)) {
        return callback(null, true);
      }
      return callback(createHttpError14.Forbidden("Origin not allowed by CORS"));
    },
    methods: ["GET", "POST", "PATCH", "DELETE", "OPTIONS"],
    allowedHeaders: ["Authorization", "Content-Type"],
    maxAge: 600
  })
);
app.use("/api/v1", routes_default);
app.use((req, res, next) => {
  next(createHttpError14(404, "Route not found"));
});
app.use((err, req, res, next) => {
  if (isHttpError(err)) {
    if (err.status >= 500) {
      logger_default.error(`${err.status} ${err.message}`);
    }
    res.status(err.status).json({ message: err.message });
  } else {
    logger_default.error(`Unexpected Error: ${err}`);
    res.status(500).json({ message: "Internal Server Error" });
  }
});
var app_default = app;

// src/index.ts
var PORT = process.env.PORT || 8080;
app_default.listen(PORT, () => {
  logger_default.info(`Listening on port ${PORT}`);
});
